// Calcula si el local está abierto en zona horaria America/Bogota
const now = new Date();
const bogota = new Date(now.getTime() - 5 * 60 * 60 * 1000);
const day = bogota.getUTCDay(); // 0=Dom, 1=Lun, 2=Mar, 3=Mie, 4=Jue, 5=Vie, 6=Sab
const minutesNow = bogota.getUTCHours() * 60 + bogota.getUTCMinutes();
const OPENS = 16 * 60;            // 4:00 pm
const CLOSE_WEEK = 21 * 60 + 30;  // 9:30 pm (Mar-Jue)
const CLOSE_WEEKEND = 22 * 60 + 30; // 10:30 pm (Vie-Dom)

let is_open = false;
let close_str = '';
let next_open = '';

if (day === 1) {
  is_open = false;
  close_str = 'Lunes cerrado';
  next_open = 'martes 4:00pm';
} else if (day >= 2 && day <= 4) {
  is_open = minutesNow >= OPENS && minutesNow < CLOSE_WEEK;
  close_str = '9:30pm';
  next_open = minutesNow < OPENS ? 'hoy 4:00pm' : 'mañana 4:00pm';
} else {
  is_open = minutesNow >= OPENS && minutesNow < CLOSE_WEEKEND;
  close_str = '10:30pm';
  next_open = minutesNow < OPENS ? 'hoy 4:00pm' : (day === 0 ? 'martes 4:00pm (lunes cerrado)' : 'mañana 4:00pm');
}

return {
  ...$json,
  is_open: is_open,
  close_str: close_str,
  next_open: next_open,
  bogota_iso: bogota.toISOString(),
  day_of_week: day,
  minutes_now: minutesNow
};
